func (t Resource) Discriminator() (string, error) {
	var discriminator struct {
		Discriminator string `json:"type"`
	}
	err := json.Unmarshal(t.union, &discriminator)
	return discriminator.Discriminator, err
}

func (t Resource) ValueByDiscriminator() (interface{}, error) {
	discriminator, err := t.Discriminator()
	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "dns.record":
		return t.AsDnsRecordResource()
	case "ipam.address":
		return t.AsIpAddressResource()
	case "ipam.subnet":
		return t.AsSubnetResource()
	case "nsx.group":
		return t.AsSecurityGroupResource()
	case "nsx.membership":
		return t.AsGroupMembershipResource()
	case "nsx.policy":
		return t.AsFirewallRulesResource()
	case "nsx.segment":
		return t.AsSegmentResource()
	case "vsphere.drs_rule":
		return t.AsDrsRuleResource()
	case "vsphere.vm":
		return t.AsVmResource()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
}

func (t Resource) MarshalJSON() ([]byte, error) {
	b, err := t.union.MarshalJSON()
	return b, err
}

func (t *Resource) UnmarshalJSON(b []byte) error {
	err := t.union.UnmarshalJSON(b)
	return err
}

